from pathlib import Path
import json, base64, html
from urllib.parse import quote

root = Path(__file__).resolve().parents[1]
site = root / 'site'
site.mkdir(exist_ok=True)
schools = json.loads((root / 'data' / 'applications-2026.json').read_text(encoding='utf-8'))
schools.sort(key=lambda s:s['name'])
address_records = [{key: value for key, value in school.items() if key != 'classes'} for school in schools]
(root / 'data' / 'schools-and-addresses.json').write_text(
    json.dumps(address_records, ensure_ascii=False, indent=2) + '\n', encoding='utf-8'
)
fallback_cards=''.join(
    f'<article class="card"><h3>{html.escape(s["name"])}</h3><p><strong>Endereço:</strong> {html.escape(s["address"])} — {html.escape(s["region"])}, São Cristóvão — SE.</p><p><a href="https://www.google.com/maps/dir/?api=1&amp;destination={quote((s.get("previous_name") or s["full"])+", "+s["address"]+", São Cristóvão, Sergipe",safe="")}" target="_blank" rel="noopener">Como chegar ↗</a></p></article>'
    for s in schools if s.get('address')
)
fallback='<noscript><p class="note">JavaScript está desativado. Consulte a lista de endereços abaixo.</p><div class="school-list">'+fallback_cards+'</div></noscript>'
logo=base64.b64encode((root/'assets'/'saese-logo.jpeg').read_bytes()).decode()
art=base64.b64encode((root/'assets'/'sao-cristovao-illustration.jpeg').read_bytes()).decode()
template='''<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SAESE 2026 · Polo São Cristóvão</title>
<style>
:root{--blue:#214f85;--navy:#15324d;--green:#248466;--paper:#f5f7fa;--muted:#536579}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--navy);font:16px/1.6 system-ui,Segoe UI,sans-serif;background:var(--paper)}a{color:var(--blue)}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #d79500;outline-offset:4px}.wrap{max-width:1120px;margin:auto;padding:0 28px}.top{background:white;border-bottom:1px solid #dfe6ee}.top .wrap{display:flex;align-items:center;justify-content:space-between;gap:24px;padding-top:14px;padding-bottom:14px}.logo{width:170px;max-height:62px;object-fit:contain}.top nav{display:flex;gap:20px;flex-wrap:wrap}.top nav a{text-decoration:none;font-weight:650;font-size:14px}.hero{background:var(--navy);color:white;padding:52px 0}.hero .wrap{display:grid;grid-template-columns:1.8fr 1fr;gap:48px;align-items:center}.eyebrow{font-size:13px;font-weight:750;letter-spacing:.12em;text-transform:uppercase;color:#a7daca}.hero h1{font-size:clamp(36px,5vw,57px);line-height:1.08;margin:14px 0 24px;letter-spacing:-.04em}.hero p{max-width:630px;color:#dfebf5}.hero img{width:100%;max-width:270px;justify-self:end;border-radius:24px}.cta{display:inline-block;background:#ffe09a;color:#15324d;padding:12px 22px;border-radius:9px;font-weight:750;text-decoration:none;margin-top:12px}.section{padding:46px 0}h2{font-size:30px;letter-spacing:-.03em;margin:0 0 8px}h3{font-size:20px;margin:0 0 10px}.lead{color:var(--muted);margin:0 0 25px}.schedule{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{background:white;border:1px solid #dfe6ee;border-radius:15px;padding:24px}.date{font-size:28px;font-weight:800;line-height:1.2;margin:10px 0}.tag{color:var(--green);font-size:12px;font-weight:750;text-transform:uppercase;letter-spacing:.06em}.card p{margin:8px 0;color:var(--muted)}.note{padding:16px 20px;border-left:4px solid #eab74d;background:#fff5df;border-radius:0 9px 9px 0;margin:20px 0}.hours{display:flex;gap:30px;flex-wrap:wrap;padding:18px 0;font-size:17px}.finder{background:white;border-top:1px solid #dfe6ee;border-bottom:1px solid #dfe6ee}.filters{display:grid;grid-template-columns:1fr 200px;gap:16px;margin:24px 0 14px}label{font-size:14px;font-weight:650}input,select{display:block;width:100%;padding:13px;font:inherit;border:1px solid #b5c3d1;border-radius:8px;background:white;margin-top:6px}.count{color:var(--muted);font-size:14px;margin-bottom:18px}.school-list{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;align-items:start}details{border:1px solid #dfe6ee;border-radius:12px;background:white;overflow:hidden}summary{list-style:none;cursor:pointer;display:flex;gap:16px;justify-content:space-between;align-items:center;padding:20px;font-size:17px;font-weight:700}summary::-webkit-details-marker{display:none}summary::after{content:'+';font-size:25px;font-weight:400;color:var(--blue)}details[open] summary::after{content:'−'}summary small{display:block;color:var(--muted);font-size:12px;font-weight:500}.school-body{padding:0 20px 20px;border-top:1px solid #edf0f4}.school-body p{margin:14px 0;font-size:14px}.school-body h3{font-size:16px;margin-top:16px}iframe{width:100%;height:230px;border:0;border-radius:9px;background:#e7edf3}.links{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-top:14px}.route{background:var(--blue);color:white;padding:9px 14px;border-radius:7px;text-decoration:none;font-size:14px;font-weight:650}.source{font-size:12px}.map-note{font-size:12px!important;color:var(--muted)}.guide{display:grid;grid-template-columns:1fr 1fr;gap:24px}.guide ul{padding-left:22px}.guide li{margin:10px 0}footer{padding:28px 0;background:var(--navy);color:#dce7f2;font-size:13px}footer a{color:#a7daca}.draft{font-size:12px;background:#fff5df;padding:8px 28px;color:#71520a;text-align:center}.empty{padding:25px;border:1px dashed #b5c3d1;border-radius:10px;color:var(--muted)}[hidden]{display:none!important}@media(max-width:700px){.wrap{padding:0 20px}.hero{padding:35px 0}.hero .wrap{grid-template-columns:1fr;gap:24px}.hero img{display:none}.schedule,.school-list,.guide{grid-template-columns:1fr}.filters{grid-template-columns:1fr}.top .wrap{align-items:flex-start;flex-direction:column;gap:10px}.top nav{gap:18px}.section{padding:32px 0}}
@media(max-width:700px){main{display:flex;flex-direction:column}main>.hero{order:0}main>#escolas{order:1}main>#datas{order:2}main>#orientacoes{order:3}}
</style></head><body>
<div class="draft">SAESE 2026 · Escolas conforme a planilha de aplicações fornecida.</div>
<header class="top"><div class="wrap"><img class="logo" src="data:image/jpeg;base64,__LOGO__" alt="SAESE"><nav aria-label="Navegação principal"><a href="#escolas">Encontrar escola</a><a href="#datas">Datas e horários</a><a href="#orientacoes">Orientações</a></nav></div></header>
<main><section class="hero"><div class="wrap"><div><div class="eyebrow">Guia do aplicador</div><h1>SAESE 2026<br>Polo São Cristóvão</h1><p>Seja bem-vindo(a)! Encontre o endereço da sua escola, consulte o mapa e organize sua participação no treinamento e nas aplicações.</p><a class="cta" href="#escolas">Encontrar minha escola ↓</a></div><img src="data:image/jpeg;base64,__ART__" alt="Ilustração de São Cristóvão com as cores do SAESE"></div></section>
<section class="section" id="datas"><div class="wrap"><h2>Datas para se organizar</h2><p class="lead">Cronograma informado no comunicado aos aplicadores do Polo São Cristóvão — SAESE 2026.</p><div class="schedule"><article class="card"><span class="tag">Treinamento obrigatório</span><div class="date">07 novembro</div><h3>Sábado · 2026</h3><p><strong>2º ano:</strong> 8h às 12h30</p><p><strong>5º e 9º anos e 3ª série do EM:</strong> 13h30 às 18h</p></article><article class="card"><span class="tag">Semana 1 · Prioritária</span><div class="date">09 a 13 novembro</div><h3>Aplicações</h3><p>A maior parte das aplicações acontecerá nesta semana.</p></article><article class="card"><span class="tag">Semana 2 · Contingência</span><div class="date">16 a 19 novembro</div><h3>Uso em última necessidade</h3><p>Estes dias serão utilizados somente se necessário.</p></article></div><div class="hours"><span><strong>Manhã:</strong> 8h às 11h</span><span><strong>Tarde:</strong> 13h às 16h</span></div><div class="note"><strong>Local do treinamento: a divulgar.</strong> A participação no treinamento é obrigatória para todos os aplicadores.</div></div></section>
<section class="section finder" id="escolas"><div class="wrap"><h2>Onde fica a sua escola?</h2><p class="lead">Busque pelo nome ou pela região. Clique na escola para abrir o endereço, o mapa e a rota.</p><div class="note">Esta lista reúne as 37 escolas da planilha de aplicações de 2026 fornecida. As fichas mostram as turmas e os turnos registrados no arquivo. Confira a data específica de sua aplicação na convocação.</div><div class="filters"><label>Nome da escola, endereço ou região<input id="search" type="search" placeholder="Ex.: Glorita, Centro, Rita Cacete…"></label><label>Rede de ensino<select id="network"><option value="">Todas as redes</option>Municipal</option>Estadual</select></label></div><div class="count" id="count" role="status" aria-live="polite"></div><div class="school-list" id="list"></div>__FALLBACK__<p class="empty" id="empty" hidden>Nenhuma escola encontrada. Tente outra parte do nome ou selecione todas as redes.</p></div></section>
<section class="section" id="orientacoes"><div class="wrap guide"><article><h2>Antes da aplicação</h2><ul><li>Participe do treinamento correspondente ao ano ou à série em que você vai atuar.</li><li>Confira sua convocação: escola, turma, data e turno.</li><li>Consulte o endereço e planeje o trajeto com antecedência.</li><li>Em caso de dúvida sobre o local, confirme com a coordenação do polo antes de sair.</li><li>Siga as instruções e os materiais oficiais entregues no treinamento.</li></ul></article><article class="card"><span class="tag">Sobre a avaliação</span><h3>Conhecer para melhorar</h3><p>O Sistema de Avaliação da Educação Básica de Sergipe acompanha a alfabetização e a aprendizagem dos estudantes. Seus resultados ajudam a identificar necessidades e orientar ações para melhorar a educação.</p><p>Este espaço reúne as informações práticas para os aplicadores do Polo São Cristóvão.</p></article></div></section></main>
<footer><div class="wrap">SAESE 2026 · Polo São Cristóvão · Preparado para revisão em 09/10/2026.<br>Calendário: comunicado local (FONTE2). Apresentação: FONTE1. Escolas, turmas e turnos: planilha de aplicações de 2026 fornecida. Endereços: cadastro municipal, cadastro estadual e diretório complementar indicados em cada escola.<br>Os mapas são resultados de busca pelo nome e pelo endereço; os marcadores ainda precisam de validação pela coordenação.</div></footer>
<script>
const schools=__DATA__;
const norm=v=>v.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const esc=v=>v.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const list=document.getElementById('list');
schools.forEach(s=>{
const query=encodeURIComponent((s.previous_name||s.full)+', '+s.address+', São Cristóvão, Sergipe');
const d=document.createElement('details');
d.dataset.search=norm([s.name,s.full,s.previous_name||'',s.address,s.region].join(' '));d.dataset.network=s.network;
const location=s.address?`<p><strong>Endereço:</strong> ${esc(s.address)} — ${esc(s.region)}, São Cristóvão — SE.</p><p class="map-note">${esc(s.status)}.</p><iframe data-src="https://www.google.com/maps?q=${query}&output=embed" title="Mapa de busca de ${esc(s.full)}" loading="lazy" referrerpolicy="no-referrer-when-downgrade" allowfullscreen></iframe><p class="map-note">Mapa por busca. Confirme se o marcador corresponde à escola antes do deslocamento.</p><div class="links"><a class="route" href="https://www.google.com/maps/dir/?api=1&destination=${query}" target="_blank" rel="noopener">Como chegar ↗</a><a class="source" href="${esc(s.source)}" target="_blank" rel="noopener">Fonte do endereço ↗</a></div>`:`<div class="note"><strong>Endereço a confirmar.</strong> A escola consta na planilha de aplicações. O endereço e o mapa serão incluídos quando a localização for confirmada.</div>`;
const classes=`<h3>Turmas e turnos</h3><div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr><th style="text-align:left;padding:8px;border-bottom:1px solid #dfe6ee">Turma</th><th style="text-align:left;padding:8px;border-bottom:1px solid #dfe6ee">Turno</th></tr></thead><tbody>${s.classes.map(c=>`<tr><td style="padding:8px;border-bottom:1px solid #edf0f4">${esc(c.class_name)}</td><td style="padding:8px;border-bottom:1px solid #edf0f4">${esc(c.shift)}</td></tr>`).join('')}</tbody></table></div><p class="map-note">Turmas e turnos transcritos da planilha fornecida. A data por escola não consta no arquivo.</p>`;
d.innerHTML=`<summary><span>${esc(s.name)}<small>${esc(s.network)} · ${esc(s.region)}</small></span></summary><div class="school-body"><h3>${esc(s.full)}</h3>${s.previous_name?`<p><strong>Nome anterior:</strong> ${esc(s.previous_name)}.</p>`:''}${location}${classes}</div>`;
if(!s.source.startsWith('http')){const source=d.querySelector('.source');source.replaceWith(Object.assign(document.createElement('span'),{className:'source',textContent:s.source}));}
d.addEventListener('toggle',()=>{if(d.open){const f=d.querySelector('iframe');if(f&&!f.getAttribute('src'))f.src=f.dataset.src;}});list.appendChild(d)});
function filter(){const q=norm(document.getElementById('search').value.trim()),network=document.getElementById('network').value;let n=0;list.querySelectorAll('details').forEach(d=>{d.hidden=!(d.dataset.search.includes(q)&&(!network||d.dataset.network===network));if(!d.hidden)n++});document.getElementById('count').textContent=n+' escola'+(n===1?'':'s')+' encontrada'+(n===1?'':'s');document.getElementById('empty').hidden=n!==0;}
document.getElementById('search').addEventListener('input',filter);document.getElementById('network').addEventListener('change',filter);filter();
</script></body></html>'''
page=template.replace('__LOGO__',logo).replace('__ART__',art).replace('__DATA__',json.dumps(schools,ensure_ascii=False)).replace('__FALLBACK__',fallback)
(site/'index.html').write_text(page,encoding='utf-8')
print('Schools:',len(schools))
